cd /Users/aviral/Documents/ChatGPT/PS5/KytyPS5
run=$1; t=$2; shift 2
env KYTY_GAME_DIR=/Users/aviral/Documents/ChatGPT/PS5/SilentHill.ShortMessage-extracted/PPSA10112-app KYTY_MESH_SCRATCH_HOST=1 KYTY_MESH_SCRATCH_MB=256 KYTY_MESH_SCRATCH_DESCRIPTOR=1 MVK_CONFIG_USE_METAL_ARGUMENT_BUFFERS=0 MVK_CONFIG_PREFILL_METAL_COMMAND_BUFFERS=2 KYTY_FRAME_STATS=1 KYTY_FRAME_DUMP=1 KYTY_TIMEOUT_SECONDS=$t KYTY_INPUT_PROBE=1 KYTY_INPUT_PROBE_START_MS=25000 KYTY_INPUT_PROBE_INTERVAL_MS=4000 KYTY_INPUT_PROBE_HOLD_MS=250 KYTY_INPUT_PROBE_BOOTSTRAP_KEY=J KYTY_INPUT_PROBE_BOOTSTRAP_COUNT=3 KYTY_INPUT_PROBE_BOOTSTRAP_WARMUP_MS=60000 KYTY_INPUT_PROBE_KEY=F10 "$@" caffeinate -i ./harness/run.sh $run > /tmp/shrun-$run.out 2>&1
